/// The measured curves for `algorithm` / `variant`; `None` for an
/// engine whose decay is not a tail length (a convolution's IR,
/// Magneto's heads, Non-Linear's window, the feedback-only engines).
#[must_use]
pub const fn table(algorithm: AlgorithmType, variant: usize) -> Option<&'static SizedTable> {
    match (algorithm, variant) {
        (AlgorithmType::Room, 0) => Some(&ROOM_0),
        (AlgorithmType::Room, 1) => Some(&ROOM_1),
        (AlgorithmType::Room, 2) => Some(&ROOM_2),
        (AlgorithmType::Hall, 0) => Some(&HALL_0),
        (AlgorithmType::Hall, 1) => Some(&HALL_1),
        (AlgorithmType::Hall, 2) => Some(&HALL_2),
        (AlgorithmType::Plate, 0) => Some(&PLATE_0),
        (AlgorithmType::Plate, 1) => Some(&PLATE_1),
        (AlgorithmType::Plate, 2) => Some(&PLATE_2),
        (AlgorithmType::Spring, 0) => Some(&SPRING_0),
        (AlgorithmType::Spring, 1) => Some(&SPRING_1),
        (AlgorithmType::Cloud, _) => Some(&CLOUD_0),
        (AlgorithmType::Bloom, _) => Some(&BLOOM_0),
        (AlgorithmType::Shimmer, _) => Some(&SHIMMER_0),
        (AlgorithmType::Chorale, _) => Some(&CHORALE_0),
        (AlgorithmType::Swell, _) => Some(&SWELL_0),
        (AlgorithmType::Random, _) => Some(&RANDOM_0),
        _ => None,
    }
}

